#### Flow 2: Message Relay (Polling-Based)

```csharp
public class OutboxMessageRelay : BackgroundService
{
    private readonly IServiceScopeFactory _scopeFactory;
    private readonly ILogger<OutboxMessageRelay> _logger;
    private readonly TimeSpan _pollingInterval = TimeSpan.FromSeconds(5);

    protected override async Task ExecuteAsync(CancellationToken stoppingToken)
    {
        _logger.LogInformation("Outbox Message Relay started");

        while (!stoppingToken.IsCancellationRequested)
        {
            try
            {
                await ProcessOutboxEventsAsync(stoppingToken);
            }
            catch (Exception ex)
            {
                _logger.LogError(ex, "Error processing outbox events");
            }

            await Task.Delay(_pollingInterval, stoppingToken);
        }
    }

    private async Task ProcessOutboxEventsAsync(CancellationToken cancellationToken)
    {
        using var scope = _scopeFactory.CreateScope();
        var dbContext = scope.ServiceProvider.GetRequiredService<ClaimsDbContext>();
        var serviceBus = scope.ServiceProvider.GetRequiredService<IServiceBusClient>();

        // Step 1: Query unpublished events (ordered by creation time)
        var unpublishedEvents = await dbContext.Outbox
            .Where(e => !e.Published)
            .OrderBy(e => e.CreatedAt)
            .Take(100) // Process in batches to avoid overwhelming broker
            .ToListAsync(cancellationToken);

        if (!unpublishedEvents.Any())
            return; // No events to process

        _logger.LogInformation("Processing {Count} unpublished outbox events", unpublishedEvents.Count);

        // Step 2: Publish each event to message broker
        foreach (var outboxEvent in unpublishedEvents)
        {
            try
            {
                // Publish to broker with retry policy
                await serviceBus.PublishAsync(
                    topic: outboxEvent.EventType,
                    message: outboxEvent.Payload,
                    correlationId: outboxEvent.AggregateId);

                // Step 3: Mark as published
                outboxEvent.Published = true;
                outboxEvent.PublishedAt = DateTime.UtcNow;

                _logger.LogInformation("Published outbox event {Id} type {EventType} for aggregate {AggregateId}",
                    outboxEvent.Id, outboxEvent.EventType, outboxEvent.AggregateId);
            }
            catch (Exception ex)
            {
                // Publish failed - leave Published=false, will retry on next poll
                _logger.LogError(ex, "Failed to publish outbox event {Id}, will retry", outboxEvent.Id);
                // Don't update Published flag - event remains in queue for retry
            }
        }

        // Step 4: Save published flags
        await dbContext.SaveChangesAsync(cancellationToken);
    }
}
```

**Relay Characteristics**:
- **Polling Interval**: 5-second default provides <5 second event latency; tune based on requirements (1 second for real-time, 30 seconds for batch)
- **Batch Processing**: Process 100 events per poll to balance throughput and memory
- **Ordered Processing**: Query `ORDER BY created_at` preserves event creation order (not strict guarantee but best-effort)
- **Retry Logic**: Failed publishes leave Published=false, so event retried on next poll (exponential backoff handled by polling interval increase on repeated failures)
- **Idempotency**: Relay may crash after publishing but before saving Published=true flag, causing duplicate publish—consumers must be idempotent

