public class OutboxEvent
{
    public long Id { get; set; }
    public string EventType { get; set; } = null!;
    public string AggregateId { get; set; } = null!;
    public string Payload { get; set; } = null!;
    public bool Published { get; set; }
    public DateTime? PublishedAt { get; set; }
    public DateTime CreatedAt { get; set; } = DateTime.UtcNow;
    public int PublishAttempts { get; set; }
    public string? LastError { get; set; }
}

public class ClaimsDbContext : DbContext
{
    public DbSet<ClaimRecord> Claims { get; set; }
    public DbSet<OutboxEvent> Outbox { get; set; }

    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        modelBuilder.Entity<OutboxEvent>(entity =>
        {
            entity.ToTable("Outbox");
            entity.HasKey(e => e.Id);
            entity.Property(e => e.EventType).HasMaxLength(255).IsRequired();
            entity.Property(e => e.AggregateId).HasMaxLength(100).IsRequired();
            entity.Property(e => e.Payload).IsRequired();
            entity.Property(e => e.Published).IsRequired().HasDefaultValue(false);
            entity.HasIndex(e => new { e.Published, e.CreatedAt })
                .HasFilter("[Published] = 0");
        });
    }
}
```

**Step 3: Implement Outbox Writer in Business Service**

```csharp
public class ClaimsService
{
    private readonly ClaimsDbContext _dbContext;
    private readonly ILogger<ClaimsService> _logger;

    public async Task<ClaimDecision> AdjudicateClaimAsync(Claim claim)
    {
        var decision = await _adjudicationEngine.EvaluateClaimAsync(claim);

        // Start database transaction
        using var transaction = await _dbContext.Database.BeginTransactionAsync();

        try
        {
            // Business logic: Save claim
            var claimRecord = new ClaimRecord
            {
                ClaimId = claim.Id,
                Status = decision.Status,
                ApprovedAmount = decision.Amount,
                AdjudicationDate = DateTime.UtcNow
            };
            await _dbContext.Claims.AddAsync(claimRecord);

            // Outbox: Save event for message relay
            var claimEvent = new ClaimAdjudicatedEvent
            {
                ClaimId = claim.Id,
                Status = decision.Status,
                Amount = decision.Amount,
                ProviderId = claim.ProviderId,
                MemberId = claim.MemberId,
                AdjudicationDate = DateTime.UtcNow
            };

            await _dbContext.Outbox.AddAsync(new OutboxEvent
            {
                EventType = "claim.adjudicated",
                AggregateId = claim.Id,
                Payload = JsonSerializer.Serialize(claimEvent),
                Published = false,
                CreatedAt = DateTime.UtcNow
            });

            // Atomic commit
            await _dbContext.SaveChangesAsync();
            await transaction.CommitAsync();

            _logger.LogInformation("Claim {ClaimId} adjudicated: {Status} ${Amount}",
                claim.Id, decision.Status, decision.Amount);

            return decision;
        }
        catch (Exception ex)
        {
            await transaction.RollbackAsync();
            _logger.LogError(ex, "Failed to adjudicate claim {ClaimId}", claim.Id);
            throw;
        }
    }
}
```

