#### Phase 2: Message Relay Implementation (Week 3-4)

**Step 1: Implement Polling-Based Message Relay**

```csharp
public class OutboxMessageRelay : BackgroundService
{
    private readonly IServiceScopeFactory _scopeFactory;
    private readonly ILogger<OutboxMessageRelay> _logger;
    private readonly OutboxRelayOptions _options;

    public OutboxMessageRelay(
        IServiceScopeFactory scopeFactory,
        ILogger<OutboxMessageRelay> logger,
        IOptions<OutboxRelayOptions> options)
    {
        _scopeFactory = scopeFactory;
        _logger = logger;
        _options = options.Value;
    }

    protected override async Task ExecuteAsync(CancellationToken stoppingToken)
    {
        _logger.LogInformation("Outbox Message Relay started with {Interval}s polling interval",
            _options.PollingIntervalSeconds);

        while (!stoppingToken.IsCancellationRequested)
        {
            try
            {
                await ProcessOutboxBatchAsync(stoppingToken);
            }
            catch (Exception ex)
            {
                _logger.LogError(ex, "Error processing outbox batch");
            }

            await Task.Delay(TimeSpan.FromSeconds(_options.PollingIntervalSeconds), stoppingToken);
        }

        _logger.LogInformation("Outbox Message Relay stopped");
    }

    private async Task ProcessOutboxBatchAsync(CancellationToken cancellationToken)
    {
        using var scope = _scopeFactory.CreateScope();
        var dbContext = scope.ServiceProvider.GetRequiredService<ClaimsDbContext>();
        var publisher = scope.ServiceProvider.GetRequiredService<IEventPublisher>();

        // Query unpublished events
        var events = await dbContext.Outbox
            .Where(e => !e.Published)
            .Where(e => e.PublishAttempts < _options.MaxRetryAttempts)
            .OrderBy(e => e.CreatedAt)
            .Take(_options.BatchSize)
            .ToListAsync(cancellationToken);

        if (!events.Any())
            return;

        _logger.LogInformation("Processing {Count} outbox events", events.Count);

        foreach (var outboxEvent in events)
        {
            try
            {
                // Publish to message broker
                await publisher.PublishAsync(
                    eventType: outboxEvent.EventType,
                    payload: outboxEvent.Payload,
                    correlationId: outboxEvent.AggregateId,
                    cancellationToken: cancellationToken);

                // Mark as published
                outboxEvent.Published = true;
                outboxEvent.PublishedAt = DateTime.UtcNow;
                outboxEvent.PublishAttempts++;

                _logger.LogInformation("Published outbox event {Id} type {EventType}",
                    outboxEvent.Id, outboxEvent.EventType);
            }
            catch (Exception ex)
            {
                // Publish failed - increment attempts, log error
                outboxEvent.PublishAttempts++;
                outboxEvent.LastError = ex.Message;

                _logger.LogError(ex, "Failed to publish outbox event {Id} (attempt {Attempts})",
                    outboxEvent.Id, outboxEvent.PublishAttempts);
            }
        }

        await dbContext.SaveChangesAsync(cancellationToken);
    }
}
```

