public interface IEventPublisher
{
    Task PublishAsync(string eventType, string payload, string correlationId, CancellationToken cancellationToken = default);
}

public class ServiceBusEventPublisher : IEventPublisher
{
    private readonly ServiceBusClient _client;
    private readonly ILogger<ServiceBusEventPublisher> _logger;

    public async Task PublishAsync(string eventType, string payload, string correlationId, CancellationToken cancellationToken)
    {
        var sender = _client.CreateSender(eventType); // Topic name matches event type

        var message = new ServiceBusMessage(payload)
        {
            CorrelationId = correlationId,
            ContentType = "application/json",
            MessageId = Guid.NewGuid().ToString()
        };

        await sender.SendMessageAsync(message, cancellationToken);

        _logger.LogDebug("Published {EventType} event to Service Bus with correlation {CorrelationId}",
            eventType, correlationId);
    }
}
