#### Phase 3: Production Hardening (Week 5-6)

**Step 1: Add Outbox Cleanup Job**

```csharp
public class OutboxCleanupJob : BackgroundService
{
    private readonly IServiceScopeFactory _scopeFactory;
    private readonly ILogger<OutboxCleanupJob> _logger;
    private readonly TimeSpan _cleanupInterval = TimeSpan.FromHours(24); // Daily cleanup
    private readonly TimeSpan _retentionPeriod = TimeSpan.FromDays(7);   // 7-day retention

    protected override async Task ExecuteAsync(CancellationToken stoppingToken)
    {
        while (!stoppingToken.IsCancellationRequested)
        {
            try
            {
                await CleanupPublishedEventsAsync(stoppingToken);
            }
            catch (Exception ex)
            {
                _logger.LogError(ex, "Error cleaning up outbox events");
            }

            await Task.Delay(_cleanupInterval, stoppingToken);
        }
    }

    private async Task CleanupPublishedEventsAsync(CancellationToken cancellationToken)
    {
        using var scope = _scopeFactory.CreateScope();
        var dbContext = scope.ServiceProvider.GetRequiredService<ClaimsDbContext>();

        var cutoffDate = DateTime.UtcNow.Subtract(_retentionPeriod);

        var deletedCount = await dbContext.Outbox
            .Where(e => e.Published && e.PublishedAt < cutoffDate)
            .ExecuteDeleteAsync(cancellationToken);

        _logger.LogInformation("Cleaned up {Count} published outbox events older than {Days} days",
            deletedCount, _retentionPeriod.TotalDays);
    }
}
```

**Step 2: Add Circuit Breaker for Message Broker**

```csharp
public class ResilientEventPublisher : IEventPublisher
{
    private readonly IEventPublisher _innerPublisher;
    private readonly ResiliencePipeline _pipeline;

    public ResilientEventPublisher(IEventPublisher innerPublisher)
    {
        _innerPublisher = innerPublisher;

        _pipeline = new ResiliencePipelineBuilder()
            .AddRetry(new RetryStrategyOptions
            {
                MaxRetryAttempts = 3,
                Delay = TimeSpan.FromSeconds(2),
                BackoffType = DelayBackoffType.Exponential
            })
            .AddCircuitBreaker(new CircuitBreakerStrategyOptions
            {
                FailureRatio = 0.5,
                SamplingDuration = TimeSpan.FromSeconds(30),
                MinimumThroughput = 10,
                BreakDuration = TimeSpan.FromSeconds(60)
            })
            .AddTimeout(TimeSpan.FromSeconds(10))
            .Build();
    }

    public async Task PublishAsync(string eventType, string payload, string correlationId, CancellationToken cancellationToken)
    {
        await _pipeline.ExecuteAsync(async ct =>
        {
            await _innerPublisher.PublishAsync(eventType, payload, correlationId, ct);
        }, cancellationToken);
    }
}
```

**Step 3: Add Dead Letter Handling for Failed Events**

```csharp
public class OutboxDeadLetterProcessor : BackgroundService
{
    private readonly IServiceScopeFactory _scopeFactory;
    private readonly ILogger<OutboxDeadLetterProcessor> _logger;
    private readonly int _maxRetryAttempts = 10;

    protected override async Task ExecuteAsync(CancellationToken stoppingToken)
    {
        while (!stoppingToken.IsCancellationRequested)
        {
            try
            {
                await ProcessDeadLetterEventsAsync(stoppingToken);
            }
            catch (Exception ex)
            {
                _logger.LogError(ex, "Error processing dead letter events");
            }

            await Task.Delay(TimeSpan.FromMinutes(15), stoppingToken);
        }
    }

    private async Task ProcessDeadLetterEventsAsync(CancellationToken cancellationToken)
    {
        using var scope = _scopeFactory.CreateScope();
        var dbContext = scope.ServiceProvider.GetRequiredService<ClaimsDbContext>();

        // Find events that exceeded max retry attempts
        var deadLetterEvents = await dbContext.Outbox
            .Where(e => !e.Published && e.PublishAttempts >= _maxRetryAttempts)
            .ToListAsync(cancellationToken);

        foreach (var evt in deadLetterEvents)
        {
            _logger.LogCritical(
                "Outbox event {Id} type {EventType} exceeded max retry attempts {MaxAttempts}. Last error: {Error}",
                evt.Id, evt.EventType, _maxRetryAttempts, evt.LastError);

            // Alert operations team
            // Move to dead letter table or archive for manual investigation
        }
    }
}
```

